// §5.3 step 3, under LockLiveOAuthGrant's lock: the refresh token is used -- by this ONE conditional
// statement (the `UPDATE tags SET last_ctr ... WHERE last_ctr < $2` shape). A row: normal rotation,
// mint the new pair in the same transaction. No row: GetOAuthRefreshTokenState says which branch.
func (q *Queries) RotateOAuthRefreshToken(ctx context.Context, arg RotateOAuthRefreshTokenParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, rotateOAuthRefreshToken, arg.TenantID, arg.TokenID)
	var grant_id uuid.UUID
	err := row.Scan(&grant_id)
	return grant_id, err
}

const setOAuthCodeGrant = `-- name: SetOAuthCodeGrant :execrows
UPDATE oauth_codes
SET grant_id = $1::uuid
WHERE tenant_id = $2
  AND id = $3
  AND consumed_at IS NOT NULL
  AND grant_id IS NULL
`

type SetOAuthCodeGrantParams struct {
	GrantID  uuid.UUID
	TenantID uuid.UUID
	CodeID   uuid.UUID
}

// §5.2 step 7: the grant the code bore, in the exchange's transaction -- what a later presentation
// of the spent code revokes. One way (00104's trigger): only a consumed code without a grant.
func (q *Queries) SetOAuthCodeGrant(ctx context.Context, arg SetOAuthCodeGrantParams) (int64, error) {
	result, err := q.db.Exec(ctx, setOAuthCodeGrant, arg.GrantID, arg.TenantID, arg.CodeID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const supersedeLiveOAuthGrants = `-- name: SupersedeLiveOAuthGrants :many

UPDATE oauth_grants
SET revoked_at = COALESCE(revoked_at, clock_timestamp()),
    revoked_reason = 'superseded'
WHERE tenant_id = $1
  AND client_id = $2
  AND revoked_at IS NULL
RETURNING id
`

type SupersedeLiveOAuthGrantsParams struct {
	TenantID uuid.UUID
	ClientID uuid.UUID
}

// ---------------------------------------------------------------------------
// The grant (§5.2 step 7, §6, §12)
// ---------------------------------------------------------------------------
// §5.2 step 7: the business's live grant to this app, if any, is replaced -- before the new one is
// inserted, in the same transaction (O-8). Its tokens die with it (the resolver reads the grant's
// revoked_at). The ids come back for the audit trail. Two exchanges racing for one (business, app)
// meet at oauth_grants_live_client_key on the INSERT below and the loser rolls back.
func (q *Queries) SupersedeLiveOAuthGrants(ctx context.Context, arg SupersedeLiveOAuthGrantsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, supersedeLiveOAuthGrants, arg.TenantID, arg.ClientID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const touchOAuthGrant = `-- name: TouchOAuthGrant :execrows
UPDATE oauth_grants
SET last_used_at = clock_timestamp()
WHERE tenant_id = $1
  AND id = $2
  AND revoked_at IS NULL
  AND (last_used_at IS NULL OR last_used_at <= clock_timestamp() - interval '1 minute')
`

type TouchOAuthGrantParams struct {
	TenantID uuid.UUID
	ID       uuid.UUID
}

// §8.1 step 6: last_used_at at most once a minute per grant (TouchAPIKey's rule), the "Connected
// apps" list's last use. A revoked grant is not touched.
func (q *Queries) TouchOAuthGrant(ctx context.Context, arg TouchOAuthGrantParams) (int64, error) {
	result, err := q.db.Exec(ctx, touchOAuthGrant, arg.TenantID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
